q=Path('/workspace/qa-cinderwatch');out=Path('/workspace/wanxiang-cloud-tour/cinderwatch-reference/evidence');r=json.loads((q/'public-smoke.json').read_text());v=r['video'];path=out/'cloud-touch-15s.mp4';subprocess.run(['ffmpeg','-y','-hide_banner','-loglevel','error','-ss',str(v['continuousStartOffset']),'-i',v['rawPath'],'-t','15','-an','-c:v','libx264','-preset','fast','-crf','19','-pix_fmt','yuv420p','-movflags','+faststart',str(path)],check=True);meta=json.loads(subprocess.check_output(['ffprobe','-v','error','-show_entries','format=duration:stream=width,height,r_frame_rate','-of','json',str(path)]));meta.update({'source':'public WebKit native touch recording','clipStartSeconds':v['continuousStartOffset'],'timeScaleChanged':False,'simulatedOrOfflineRender':False,'gameFPS':r['measuredFPS'],'encoded25fpsIsNotGameFPS':True,'SHA256':hashlib.sha256(path.read_bytes()).hexdigest()});(out/'cloud-touch-video.json').write_text(json.dumps(meta,ensure_ascii=False,indent=2)+'\n');print(json.dumps(meta,indent=2))
